parameters.jsCode:
// Normalize direct sub-workflow input and the protected webhook envelope
// into the same plain WF06 payload object.

const input = $json ?? {};

const payload =
  input.body !== null &&
  typeof input.body === 'object' &&
  !Array.isArray(input.body)
    ? input.body
    : input;

return {
  json: payload,
};

// Validate the WF06 invocation before any database state is changed.

const input = $json;

if (
  input === null ||
  typeof input !== 'object' ||
  Array.isArray(input)
) {
  throw new Error('WF06 invocation must be a JSON object');
}

const allowedFields = new Set([
  'case_id',
  'correlation_id',
  'trigger_source',
  'client_id',
  'accepted_submission_id',
  'external_client_id',
  'external_operation_id',
  'recovery_reason',
]);

const unknownFields = Object.keys(input).filter(
  (field) => !allowedFields.has(field),
);

if (unknownFields.length > 0) {
  throw new Error(
    `WF06 invocation contains unknown fields: ${unknownFields.join(', ')}`,
  );
}

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function requireUuid(value, fieldName) {
  if (
    typeof value !== 'string' ||
    !uuidPattern.test(value)
  ) {
    throw new Error(
      `WF06 ${fieldName} must be a valid UUID`,
    );
  }

  return value.toLowerCase();
}

function optionalUuid(value, fieldName) {
  if (value === undefined || value === null) {
    return null;
  }

  return requireUuid(value, fieldName);
}

function requireNonEmptyString(value, fieldName) {
  if (
    typeof value !== 'string' ||
    value.trim() === ''
  ) {
    throw new Error(
      `WF06 ${fieldName} must be a non-empty string`,
    );
  }

  return value.trim();
}

const caseId = requireUuid(
  input.case_id,
  'case_id',
);

const correlationId = requireUuid(
  input.correlation_id,
  'correlation_id',
);

if (
  input.trigger_source !== 'wf05' &&
  input.trigger_source !== 'wf98'
) {
  throw new Error(
    'WF06 trigger_source must be either wf05 or wf98',
  );
}

if (input.trigger_source === 'wf05') {
  const clientId = requireUuid(
    input.client_id,
    'client_id',
  );

  const acceptedSubmissionId = requireUuid(
    input.accepted_submission_id,
    'accepted_submission_id',
  );

  const externalClientId = requireNonEmptyString(
    input.external_client_id,
    'external_client_id',
  );

  if (
    input.external_operation_id !== undefined &&
    input.external_operation_id !== null
  ) {
    throw new Error(
      'WF06 wf05 invocation must not contain external_operation_id',
    );
  }

  if (
    input.recovery_reason !== undefined &&
    input.recovery_reason !== null
  ) {
    throw new Error(
      'WF06 wf05 invocation must not contain recovery_reason',
    );
  }

  return {
    json: {
      case_id: caseId,
      correlation_id: correlationId,
      trigger_source: 'wf05',
      client_id: clientId,
      accepted_submission_id: acceptedSubmissionId,
      external_client_id: externalClientId,
      external_operation_id: null,
      recovery_reason: null,
    },
  };
}

if (
  input.client_id !== undefined &&
  input.client_id !== null
) {
  throw new Error(
    'WF06 wf98 invocation must not contain client_id',
  );
}

if (
  input.accepted_submission_id !== undefined &&
  input.accepted_submission_id !== null
) {
  throw new Error(
    'WF06 wf98 invocation must not contain accepted_submission_id',
  );
}

if (
  input.external_client_id !== undefined &&
  input.external_client_id !== null
) {
  throw new Error(
    'WF06 wf98 invocation must not contain external_client_id',
  );
}

const externalOperationId = optionalUuid(
  input.external_operation_id,
  'external_operation_id',
);

let recoveryReason = null;

if (
  input.recovery_reason !== undefined &&
  input.recovery_reason !== null
) {
  if (typeof input.recovery_reason !== 'string') {
    throw new Error(
      'WF06 recovery_reason must be a string',
    );
  }

  recoveryReason = input.recovery_reason;
}

if (
  externalOperationId !== null &&
  recoveryReason !== null
) {
  throw new Error(
    'WF06 wf98 invocation must not contain both external_operation_id and recovery_reason',
  );
}

if (
  externalOperationId === null &&
  ![
    'missing_initial_dispatch',
    'resume_finalization',
    'complete_finalization',
  ].includes(recoveryReason)
) {
  throw new Error(
    'WF06 wf98 invocation requires external_operation_id or a valid recovery_reason',
  );
}

return {
  json: {
    case_id: caseId,
    correlation_id: correlationId,
    trigger_source: 'wf98',
    client_id: null,
    accepted_submission_id: null,
    external_client_id: null,
    external_operation_id: externalOperationId,
    recovery_reason: recoveryReason,
  },
};

// Build the WF06 runtime context used by PostgreSQL preparation.
// Provider configuration remains outside the invocation payload.

const input = $json ?? {};

function requireText(value, fieldName) {
  const normalized = String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(
      `${fieldName} must not be blank`,
    );
  }

  return normalized;
}

function optionalText(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized = String(value).trim();

  return normalized === ''
    ? null
    : normalized;
}

function optionalBoolean(value) {
  const normalized = optionalText(value);

  if (normalized === null) {
    return null;
  }

  if (normalized.toLowerCase() === 'true') {
    return true;
  }

  if (normalized.toLowerCase() === 'false') {
    return false;
  }

  return null;
}

function optionalJsonArray(value) {
  const normalized = optionalText(value);

  if (normalized === null) {
    return null;
  }

  try {
    const parsed = JSON.parse(normalized);

    return Array.isArray(parsed)
      ? parsed
      : null;
  } catch {
    return null;
  }
}

const executionId = requireText(
  $execution.id,
  'execution_id',
);

const configuration = {
  drive_parent_folder_id:
    optionalText(
      $env.GOOGLE_DRIVE_PARENT_FOLDER_ID,
    ),

  drive_use_shared_drive:
    optionalBoolean(
      $env.GOOGLE_DRIVE_USE_SHARED_DRIVE,
    ),

  drive_folder_name_template:
    optionalText(
      $env.WF06_DRIVE_FOLDER_NAME_TEMPLATE,
    ),

  calendar_id:
    optionalText(
      $env.GOOGLE_CALENDAR_ID,
    ),

  kickoff_timezone:
    optionalText(
      $env.KICKOFF_TIMEZONE,
    ),

  kickoff_delay_days:
    optionalText(
      $env.KICKOFF_DELAY_DAYS,
    ),

  kickoff_start_local_time:
    optionalText(
      $env.KICKOFF_START_LOCAL_TIME,
    ),

  kickoff_duration_minutes:
    optionalText(
      $env.KICKOFF_DURATION_MINUTES,
    ),

  kickoff_internal_attendee_email:
    optionalText(
      $env.KICKOFF_INTERNAL_ATTENDEE_EMAIL,
    ),

  team_notification_recipients:
    optionalJsonArray(
      $env.TEAM_NOTIFICATION_RECIPIENTS,
    ),

  team_notification_sender_name:
    optionalText(
      $env.TEAM_NOTIFICATION_SENDER_NAME,
    ),

  team_notification_template_key:
    optionalText(
      $env.TEAM_NOTIFICATION_TEMPLATE_KEY,
    ),
};

return {
  json: {
    ...input,

    execution_id:
      executionId,

    configuration,

    lease_seconds:
      300,

    max_attempts:
      5,
  },
};

// Normalize the authoritative PostgreSQL WF06 preparation result
// before routing to an external operation, completion, no-action,
// or operator intervention.

const row = $json ?? {};

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function requireText(value, fieldName) {
  const normalized = String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(
      `${fieldName} must not be blank`,
    );
  }

  return normalized;
}

function optionalText(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized = String(value).trim();

  return normalized === ''
    ? null
    : normalized;
}

if (!isPlainObject(row.input_context)) {
  throw new Error(
    'WF06 input_context must be a JSON object',
  );
}

if (!isPlainObject(row.preparation_result)) {
  throw new Error(
    'WF06 preparation_result must be a JSON object',
  );
}

const inputContext =
  row.input_context;

const result =
  row.preparation_result;

const preparationOutcome = requireText(
  result.preparation_outcome,
  'preparation_outcome',
);

let nextAction;

if (preparationOutcome === 'claimed') {
  nextAction =
    'process_operation';

} else if (
  preparationOutcome === 'ready_to_complete'
) {
  nextAction =
    'complete_onboarding';

} else if (
  new Set([
    'already_completed',
    'not_required',
    'busy',
    'not_due',
  ]).has(preparationOutcome)
) {
  nextAction =
    'no_action';

} else {
  nextAction =
    'operator_intervention_required';
}

if (nextAction === 'process_operation') {
  const allowedOperationTypes =
    new Set([
      'create_drive_folder',
      'create_kickoff_event',
      'notify_team',
    ]);

  const operationType = requireText(
    result.operation_type,
    'operation_type',
  );

  if (!allowedOperationTypes.has(operationType)) {
    throw new Error(
      `WF06 received unsupported operation_type: ${operationType}`,
    );
  }

  requireText(
    result.operation_id,
    'operation_id',
  );

  requireText(
    result.lease_owner,
    'lease_owner',
  );

  requireText(
    result.lease_expires_at,
    'lease_expires_at',
  );

  if (!isPlainObject(result.request_summary)) {
    throw new Error(
      'WF06 claimed operation must contain request_summary',
    );
  }

  if (result.case_state !== 'finalizing') {
    throw new Error(
      'WF06 claimed operation must have case_state=finalizing',
    );
  }

  if (result.operation_status !== 'in_progress') {
    throw new Error(
      'WF06 claimed operation must have operation_status=in_progress',
    );
  }
}

if (
  nextAction === 'complete_onboarding' &&
  result.case_state !== 'finalizing'
) {
  throw new Error(
    'WF06 completion preparation must have case_state=finalizing',
  );
}

return {
  json: {
    ...inputContext,
    ...result,

    workflow:
      'WF06',

    preparation_outcome:
      preparationOutcome,

    next_action:
      nextAction,

    error_code:
      optionalText(result.error_code),
  },
};

// Return a controlled WF06 result when no external action is required.

const input = $json ?? {};

if (input.next_action !== 'no_action') {
  throw new Error(
    'Return Finalization No Action Result received an invalid next action',
  );
}

const allowedOutcomes = new Set([
  'already_completed',
  'not_required',
  'busy',
  'not_due',
]);

if (!allowedOutcomes.has(input.preparation_outcome)) {
  throw new Error(
    `Unsupported WF06 no-action outcome: ${input.preparation_outcome}`,
  );
}

return {
  json: {
    workflow:
      'WF06',

    result:
      input.preparation_outcome,

    case_id:
      input.case_id ?? null,

    correlation_id:
      input.correlation_id ?? null,

    case_state:
      input.case_state ?? null,

    external_client_id:
      input.external_client_id ?? null,

    drive_folder_id:
      input.drive_folder_id ?? null,

    kickoff_event_id:
      input.kickoff_event_id ?? null,

    team_message_id:
      input.team_message_id ?? null,

    operation_id:
      input.operation_id ?? null,

    operation_type:
      input.operation_type ?? null,

    operation_status:
      input.operation_status ?? null,

    operation_claim_outcome:
      input.operation_claim_outcome ?? null,
  },
};

parameters.query:
SELECT
    $3::jsonb AS input_context,
    complete_wf06_onboarding(
        $1::uuid,
        $2::uuid
    ) AS completion_result;

parameters.jsCode:
// Normalize and validate the authoritative PostgreSQL
// onboarding completion result.

const row = $json ?? {};

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function requireText(value, fieldName) {
  const normalized = String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(
      `${fieldName} must not be blank`,
    );
  }

  return normalized;
}

function optionalText(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const normalized = String(value).trim();

  return normalized === ''
    ? null
    : normalized;
}

if (!isPlainObject(row.input_context)) {
  throw new Error(
    'WF06 completion input_context must be a JSON object',
  );
}

if (!isPlainObject(row.completion_result)) {
  throw new Error(
    'WF06 completion_result must be a JSON object',
  );
}

const inputContext =
  row.input_context;

const result =
  row.completion_result;

const completionOutcome = requireText(
  result.completion_outcome,
  'completion_outcome',
);

const successfulOutcomes = new Set([
  'completed',
  'already_completed',
]);

let nextAction;

if (successfulOutcomes.has(completionOutcome)) {
  const requiredSuccessFields = [
    'case_id',
    'correlation_id',
    'external_client_id',
    'drive_folder_id',
    'kickoff_event_id',
    'team_message_id',
  ];

  for (const fieldName of requiredSuccessFields) {
    requireText(
      result[fieldName],
      fieldName,
    );
  }

  if (result.case_state !== 'completed') {
    throw new Error(
      'WF06 successful completion must have case_state=completed',
    );
  }

  nextAction =
    'return_completed';

} else {
  nextAction =
    'operator_intervention_required';
}

return {
  json: {
    ...inputContext,
    ...result,

    workflow:
      'WF06',

    completion_outcome:
      completionOutcome,

    next_action:
      nextAction,

    error_code:
      optionalText(result.error_code),
  },
};

// Return the sanitized terminal WF06 completion result.

const input = $json ?? {};

if (input.next_action !== 'return_completed') {
  throw new Error(
    'Return Finalization Completed Result received an invalid next action',
  );
}

if (
  input.completion_outcome !== 'completed' &&
  input.completion_outcome !== 'already_completed'
) {
  throw new Error(
    'WF06 completion outcome is not successful',
  );
}

if (input.case_state !== 'completed') {
  throw new Error(
    'WF06 final result must have case_state=completed',
  );
}

return {
  json: {
    workflow:
      'WF06',

    result:
      input.completion_outcome,

    case_id:
      input.case_id,

    correlation_id:
      input.correlation_id,

    case_state:
      input.case_state,

    external_client_id:
      input.external_client_id,

    drive_folder_id:
      input.drive_folder_id,

    kickoff_event_id:
      input.kickoff_event_id,

    team_message_id:
      input.team_message_id,

    completed_at:
      input.completed_at ?? null,
  },
};

// Build the deterministic Google Drive reconciliation query
// and the exact folder creation request.

const input = $json ?? {};

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function requireText(value, fieldName) {
  const normalized = String(value ?? '').trim();

  if (normalized === '') {
    throw new Error(
      `${fieldName} must not be blank`,
    );
  }

  return normalized;
}

function escapeDriveQueryValue(value) {
  return value
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'");
}

if (
  input.next_action !== 'process_operation' ||
  input.operation_type !== 'create_drive_folder'
) {
  throw new Error(
    'Build Drive Reconciliation Request received an invalid operation',
  );
}

if (!isPlainObject(input.request_summary)) {
  throw new Error(
    'Drive request_summary must be a JSON object',
  );
}

const request =
  input.request_summary;

const parentFolderId = requireText(
  request.parent_folder_id,
  'parent_folder_id',
);

const folderName = requireText(
  request.folder_name,
  'folder_name',
);

const mimeType = requireText(
  request.mime_type,
  'mime_type',
);

const onboardingCaseId = requireText(
  request.onboarding_case_id,
  'onboarding_case_id',
);

const operationKeyHash = requireText(
  request.operation_key_hash,
  'operation_key_hash',
).toLowerCase();

if (
  mimeType !==
  'application/vnd.google-apps.folder'
) {
  throw new Error(
    'Drive request contains an invalid folder MIME type',
  );
}

if (onboardingCaseId !== input.case_id) {
  throw new Error(
    'Drive onboarding_case_id does not match case_id',
  );
}

if (
  !/^[0-9a-f]{32}$/.test(operationKeyHash)
) {
  throw new Error(
    'Drive operation_key_hash must contain 32 lowercase hexadecimal characters',
  );
}

if (
  typeof request.use_shared_drive !==
  'boolean'
) {
  throw new Error(
    'Drive use_shared_drive must be a boolean',
  );
}

const escapedParentFolderId =
  escapeDriveQueryValue(parentFolderId);

const escapedCaseId =
  escapeDriveQueryValue(onboardingCaseId);

const escapedOperationKeyHash =
  escapeDriveQueryValue(operationKeyHash);

const searchQuery = [
  `'${escapedParentFolderId}' in parents`,
  `mimeType = '${mimeType}'`,
  'trashed = false',
  `appProperties has { key='onboardingCaseId' and value='${escapedCaseId}' }`,
  `appProperties has { key='operationKeyHash' and value='${escapedOperationKeyHash}' }`,
].join(' and ');

return {
  json: {
    ...input,

    provider:
      'google_drive',

    drive_search_query:
      searchQuery,

    drive_expected: {
      parent_folder_id:
        parentFolderId,

      folder_name:
        folderName,

      mime_type:
        mimeType,

      onboarding_case_id:
        onboardingCaseId,

      operation_key_hash:
        operationKeyHash,

      use_shared_drive:
        request.use_shared_drive,
    },

    drive_create_request_body: {
      name:
        folderName,

      mimeType:
        mimeType,

      parents: [
        parentFolderId,
      ],

      appProperties: {
        onboardingCaseId:
          onboardingCaseId,

        operationKeyHash:
          operationKeyHash,
      },
    },

    provider_request_started_at:
      new Date().toISOString(),
  },
};

const input = $json;
const receivedAt = new Date().toISOString();

const isObject = (value) =>
  value !== null &&
  typeof value === 'object' &&
  !Array.isArray(value);

const requireString = (value, fieldName) => {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new Error(`${fieldName} must be a non-empty string`);
  }

  return value.trim();
};

const parseHttpStatus = (value) => {
  const parsed = Number(value);

  return Number.isInteger(parsed) &&
    parsed >= 100 &&
    parsed <= 599
    ? parsed
    : null;
};

const parseRetryAfterSeconds = (headers) => {
  if (!isObject(headers)) {
    return null;
  }

  const raw =
    headers['retry-after'] ??
    headers['Retry-After'] ??
    null;

  if (raw === null || raw === undefined) {
    return null;
  }

  const seconds = Number(raw);

  if (Number.isFinite(seconds) && seconds >= 0) {
    return Math.ceil(seconds);
  }

  const retryAt = Date.parse(String(raw));

  return Number.isFinite(retryAt)
    ? Math.max(0, Math.ceil((retryAt - Date.now()) / 1000))
    : null;
};

requireString(input.case_id, 'case_id');
requireString(input.operation_id, 'operation_id');
requireString(input.lease_owner, 'lease_owner');

if (!isObject(input.drive_expected)) {
  throw new Error('drive_expected must be an object');
}

const expected = {
  parent_folder_id: requireString(
    input.drive_expected.parent_folder_id,
    'drive_expected.parent_folder_id'
  ),
  folder_name: requireString(
    input.drive_expected.folder_name,
    'drive_expected.folder_name'
  ),
  mime_type: requireString(
    input.drive_expected.mime_type,
    'drive_expected.mime_type'
  ),
  onboarding_case_id: requireString(
    input.drive_expected.onboarding_case_id,
    'drive_expected.onboarding_case_id'
  ),
  operation_key_hash: requireString(
    input.drive_expected.operation_key_hash,
    'drive_expected.operation_key_hash'
  ),
  use_shared_drive:
    input.drive_expected.use_shared_drive === true,
};

if (expected.mime_type !== 'application/vnd.google-apps.folder') {
  throw new Error(
    'drive_expected.mime_type must identify a Google Drive folder'
  );
}

const httpStatus = parseHttpStatus(
  input.statusCode ??
  input.status_code ??
  input.http_status
);

const headers = isObject(input.headers)
  ? input.headers
  : {};

const body = isObject(input.body)
  ? input.body
  : null;

const retryAfterSeconds = parseRetryAfterSeconds(headers);

const buildResult = (overrides) => ({
  json: {
    ...input,
    workflow: 'WF06',
    provider: 'google_drive',
    http_status: httpStatus,
    provider_response_received_at: receivedAt,
    ...overrides,
  },
});

const buildFailure = ({
  providerOutcome,
  nextAction,
  errorClass,
  errorCode,
  errorMessage,
  retryable,
  responseSummary = null,
}) =>
  buildResult({
    provider_outcome: providerOutcome,
    next_action: nextAction,
    external_id: null,
    reconciled: false,
    provider_response_summary: responseSummary,
    error_class: errorClass,
    error_code: errorCode,
    error_message: errorMessage,
    retryable,
    provider_retry_after_seconds: retryAfterSeconds,
  });

const transportError = isObject(input.error)
  ? input.error
  : typeof input.error === 'string' && input.error.trim() !== ''
    ? { message: input.error.trim() }
    : null;

if (transportError !== null && httpStatus === null) {
  return buildFailure({
    providerOutcome: 'transport_error',
    nextAction: 'finalize_retryable_failure',
    errorClass: 'transport',
    errorCode: 'drive_search_transport_error',
    errorMessage:
      typeof transportError.message === 'string' &&
      transportError.message.trim() !== ''
        ? transportError.message.trim()
        : 'Google Drive search failed before an HTTP response was received',
    retryable: true,
  });
}

if (httpStatus === null) {
  return buildFailure({
    providerOutcome: 'invalid_response',
    nextAction: 'finalize_retryable_failure',
    errorClass: 'protocol',
    errorCode: 'drive_search_missing_http_status',
    errorMessage:
      'Google Drive search did not return a valid HTTP status',
    retryable: true,
  });
}

if (httpStatus !== 200) {
  const retryable =
    httpStatus === 408 ||
    httpStatus === 425 ||
    httpStatus === 429 ||
    httpStatus >= 500;

  const providerError = isObject(body?.error)
    ? body.error
    : {};

  const providerCode =
    providerError.status ??
    providerError.code ??
    `http_${httpStatus}`;

  const providerMessage =
    typeof providerError.message === 'string' &&
    providerError.message.trim() !== ''
      ? providerError.message.trim()
      : `Google Drive search returned HTTP ${httpStatus}`;

  return buildFailure({
