          value,
          `recipients[${index}]`,
        ),
    ),
  ),
];

if (recipients.length === 0) {
  throw new Error(
    'Notification recipients must not be empty',
  );
}

const senderName = requireText(
  request.sender_name,
  'sender_name',
);

const templateKey = requireText(
  request.template_key,
  'template_key',
);

const legalName = requireText(
  request.legal_name,
  'legal_name',
);

const externalClientId = requireText(
  request.external_client_id,
  'external_client_id',
);

const driveFolderId = requireText(
  request.drive_folder_id,
  'drive_folder_id',
);

const driveFolderLink = requireHttpsUrl(
  request.drive_folder_link,
  'drive_folder_link',
);

const calendarEventId = requireText(
  request.calendar_event_id,
  'calendar_event_id',
);

const calendarEventLink = optionalText(
  request.calendar_event_link,
);

if (calendarEventLink !== null) {
  requireHttpsUrl(
    calendarEventLink,
    'calendar_event_link',
  );
}

const kickoffStartAt = requireText(
  request.kickoff_start_at,
  'kickoff_start_at',
);

const kickoffTimezone = requireText(
  request.kickoff_timezone,
  'kickoff_timezone',
);

const messageMarker = requireText(
  request.message_marker,
  'message_marker',
);

if (
  !/^b2b-team-notification-[0-9a-f]{24}$/.test(
    messageMarker,
  )
) {
  throw new Error(
    'message_marker does not match the WF06 deterministic marker format',
  );
}

if (
  externalClientId !==
  requireText(
    input.external_client_id,
    'external_client_id context',
  )
) {
  throw new Error(
    'Notification external_client_id does not match the case context',
  );
}

const kickoffTimestamp = Date.parse(
  kickoffStartAt,
);

if (!Number.isFinite(kickoffTimestamp)) {
  throw new Error(
    'kickoff_start_at must be a valid date-time',
  );
}

let kickoffDisplay;

try {
  kickoffDisplay = new Intl.DateTimeFormat(
    'en-GB',
    {
      timeZone:
        kickoffTimezone,
      dateStyle:
        'full',
      timeStyle:
        'short',
    },
  ).format(
    new Date(kickoffTimestamp),
  );
} catch {
  throw new Error(
    'kickoff_timezone must be a valid IANA time zone',
  );
}

const subject =
  `[B2B Onboarding] ${legalName} is ready`;

const textBody = [
  'B2B client onboarding has been finalized.',
  '',
  `Company: ${legalName}`,
  `External client ID: ${externalClientId}`,
  `Drive folder: ${driveFolderLink}`,
  `Kickoff: ${kickoffDisplay} (${kickoffTimezone})`,
  calendarEventLink === null
    ? `Calendar event ID: ${calendarEventId}`
    : `Calendar event: ${calendarEventLink}`,
  '',
  `Template: ${templateKey}`,
  `Message marker: ${messageMarker}`,
].join('\n');

const calendarHtml = calendarEventLink === null
  ? escapeHtml(calendarEventId)
  : `<a href="${escapeHtml(calendarEventLink)}">Open kickoff event</a>`;

const htmlBody = `
<div style="font-family: Arial, sans-serif; line-height: 1.5;">
  <h2>B2B client onboarding completed</h2>

  <table cellpadding="6" cellspacing="0" border="0">
    <tr>
      <td><strong>Company</strong></td>
      <td>${escapeHtml(legalName)}</td>
    </tr>
    <tr>
      <td><strong>External client ID</strong></td>
      <td>${escapeHtml(externalClientId)}</td>
    </tr>
    <tr>
      <td><strong>Drive folder</strong></td>
      <td>
        <a href="${escapeHtml(driveFolderLink)}">Open client folder</a>
      </td>
    </tr>
    <tr>
      <td><strong>Kickoff</strong></td>
      <td>
        ${escapeHtml(kickoffDisplay)}
        (${escapeHtml(kickoffTimezone)})
      </td>
    </tr>
    <tr>
      <td><strong>Calendar event</strong></td>
      <td>${calendarHtml}</td>
    </tr>
  </table>

  <p style="font-size: 12px; color: #666;">
    ${escapeHtml(messageMarker)}
  </p>
</div>
`.trim();

return {
  json: {
    ...input,

    provider:
      'gmail',

    gmail_search_query:
      `in:sent "${messageMarker}"`,

    notification_recipients:
      recipients,

    notification_send_to:
      recipients.join(', '),

    notification_sender_name:
      senderName,

    notification_template_key:
      templateKey,

    notification_subject:
      subject,

    notification_text:
      textBody,

    notification_html:
      htmlBody,

    notification_message_marker:
      messageMarker,

    notification_expected: {
      recipients,
      template_key:
        templateKey,
      legal_name:
        legalName,
      external_client_id:
        externalClientId,
      drive_folder_id:
        driveFolderId,
      drive_folder_link:
        driveFolderLink,
      calendar_event_id:
        calendarEventId,
      calendar_event_link:
        calendarEventLink,
      kickoff_start_at:
        kickoffStartAt,
      kickoff_timezone:
        kickoffTimezone,
      message_marker:
        messageMarker,
    },

    provider_request_started_at:
      new Date().toISOString(),
  },
};

// Convert zero, one, or several Gmail messages
// into one deterministic reconciliation result.

const inputItems = $input.all();

const messages = inputItems
  .map((item) => item.json ?? {})
  .filter((message) => {
    return (
      typeof message.id === 'string' &&
      message.id.trim() !== ''
    );
  })
  .map((message) => ({
    id:
      message.id.trim(),

    thread_id:
      typeof message.threadId === 'string' &&
      message.threadId.trim() !== ''
        ? message.threadId.trim()
        : null,

    label_ids:
      Array.isArray(message.labelIds)
        ? message.labelIds.map(String)
        : [],
  }));

return [
  {
    json: {
      gmail_search_messages:
        messages,

      gmail_search_match_count:
        messages.length,
    },
  },
];

// Normalize Gmail reconciliation into one of four deterministic routes.

const input = $json ?? {};

const firstText = (...values) => {
  for (const value of values) {
    if (typeof value === 'string' && value.trim() !== '') {
      return value.trim();
    }
  }

  return null;
};

const firstInteger = (...values) => {
  for (const value of values) {
    const parsed = Number.parseInt(String(value ?? ''), 10);

    if (Number.isInteger(parsed)) {
      return parsed;
    }
  }

  return null;
};

const buildFailure = (source) => {
  const error = source.error ?? source;

  const httpStatus = firstInteger(
    error.httpCode,
    error.statusCode,
    error.status,
    error.context?.httpStatusCode,
    error.response?.status,
    source.httpCode,
    source.statusCode,
  );

  const providerCode = firstText(
    error.code,
    error.errorCode,
    error.name,
    error.context?.errorCode,
  );

  const message = firstText(
    error.message,
    error.description,
    error.error,
    error.context?.errorMessage,
    source.message,
  ) ?? 'Gmail reconciliation search failed.';

  const retryAfter = firstInteger(
    error.retryAfter,
    error.retry_after,
    error.response?.headers?.['retry-after'],
    source.retryAfter,
  );

  const terminalStatus =
    httpStatus !== null &&
    [400, 401, 403, 404, 422].includes(httpStatus);

  let errorClass = 'reconciliation_search_error';

  if (httpStatus === 401) {
    errorClass = 'authentication_error';
  } else if (httpStatus === 403) {
    errorClass = 'authorization_error';
  } else if (httpStatus === 429) {
    errorClass = 'rate_limit_error';
  } else if (httpStatus !== null && httpStatus >= 500) {
    errorClass = 'provider_unavailable';
  } else if (
    httpStatus !== null &&
    [400, 404, 422].includes(httpStatus)
  ) {
    errorClass = 'provider_request_error';
  }

  const retryable = !terminalStatus;

  return {
    ...source,
    team_notification_search_route:
      retryable
        ? 'finalize_retryable_failure'
        : 'finalize_terminal_failure',
    provider: 'gmail',
    retryable,
    error_class: errorClass,
    error_code:
      providerCode ?? 'gmail_reconciliation_search_failed',
    error_message: message.slice(0, 1000),
    http_status: httpStatus,
    provider_retry_after_seconds: retryAfter,
  };
};

if (Array.isArray(input.gmail_search_messages)) {
  const messages = input.gmail_search_messages
    .filter((message) => {
      return (
        message &&
        typeof message.id === 'string' &&
        message.id.trim() !== ''
      );
    })
    .map((message) => ({
      id: message.id.trim(),
      thread_id:
        typeof message.thread_id === 'string' &&
        message.thread_id.trim() !== ''
          ? message.thread_id.trim()
          : null,
      label_ids:
        Array.isArray(message.label_ids)
          ? message.label_ids.map(String)
          : [],
    }));

  if (messages.length === 0) {
    return {
      json: {
        ...input,
        gmail_search_messages: messages,
        gmail_search_match_count: 0,
        team_notification_search_route:
          'send_team_notification',
        provider: 'gmail',
      },
    };
  }

  if (messages.length === 1) {
    const message = messages[0];

    return {
      json: {
        ...input,
        gmail_search_messages: messages,
        gmail_search_match_count: 1,
        team_notification_search_route:
          'finalize_success',
        provider: 'gmail',
        external_id: message.id,
        reconciled: true,
        provider_response_summary: {
          marker_verified: true,
          created: false,
          thread_id: message.thread_id,
          message_marker: input.notification_message_marker,
        },
      },
    };
  }

  return {
    json: {
      ...input,
      gmail_search_messages: messages,
      gmail_search_match_count: messages.length,
      team_notification_search_route:
        'finalize_terminal_failure',
      provider: 'gmail',
      retryable: false,
      error_class: 'reconciliation_ambiguity',
      error_code: 'multiple_matching_team_notifications',
      error_message:
        `Gmail reconciliation found ${messages.length} sent messages with the same deterministic marker.`,
      http_status: null,
      provider_retry_after_seconds: null,
    },
  };
}

return {
  json: buildFailure(input),
};

// Normalize Gmail delivery into common WF06 finalization fields.

const input = $json ?? {};

const firstText = (...values) => {
  for (const value of values) {
    if (typeof value === 'string' && value.trim() !== '') {
      return value.trim();
    }
  }

  return null;
};

const firstInteger = (...values) => {
  for (const value of values) {
    const parsed = Number.parseInt(String(value ?? ''), 10);

    if (Number.isInteger(parsed)) {
      return parsed;
    }
  }

  return null;
};

const messageId = firstText(
  input.id,
  input.messageId,
);

if (!input.error && messageId) {
  const threadId = firstText(
    input.threadId,
    input.thread_id,
  );

  return {
    json: {
      ...input,
      team_notification_delivery_route:
        'finalize_success',
      provider: 'gmail',
      external_id: messageId,
      reconciled: false,
      provider_response_summary: {
        marker_verified: true,
        created: true,
        thread_id: threadId,
        message_marker: input.notification_message_marker,
      },
    },
  };
}

const error = input.error ?? input;

const httpStatus = firstInteger(
  error.httpCode,
  error.statusCode,
  error.status,
  error.context?.httpStatusCode,
  error.response?.status,
  input.httpCode,
  input.statusCode,
);

const providerCode = firstText(
  error.code,
  error.errorCode,
  error.name,
  error.context?.errorCode,
);

const message = firstText(
  error.message,
  error.description,
  error.error,
  error.context?.errorMessage,
  input.message,
) ?? 'Gmail delivery failed.';

const retryAfter = firstInteger(
  error.retryAfter,
  error.retry_after,
  error.response?.headers?.['retry-after'],
  input.retryAfter,
);

const terminalStatus =
  httpStatus !== null &&
  [400, 401, 403, 404, 422].includes(httpStatus);

let errorClass = 'notification_delivery_error';

if (httpStatus === 401) {
  errorClass = 'authentication_error';
} else if (httpStatus === 403) {
  errorClass = 'authorization_error';
} else if (httpStatus === 429) {
  errorClass = 'rate_limit_error';
} else if (httpStatus !== null && httpStatus >= 500) {
  errorClass = 'provider_unavailable';
} else if (
  httpStatus !== null &&
  [400, 404, 422].includes(httpStatus)
) {
  errorClass = 'provider_request_error';
}

const retryable = !terminalStatus;

return {
  json: {
    ...input,
    team_notification_delivery_route:
      retryable
        ? 'finalize_retryable_failure'
        : 'finalize_terminal_failure',
    provider: 'gmail',
    retryable,
    error_class: errorClass,
    error_code:
      providerCode ?? 'gmail_notification_delivery_failed',
    error_message: message.slice(0, 1000),
    http_status: httpStatus,
    provider_retry_after_seconds: retryAfter,
  },
};

// Return a controlled WF06 result after a retryable operation failure.

const input = $json ?? {};

if (
  input.finalization_route !==
  'return_retryable_failure'
) {
  throw new Error(
    'Retryable failure result received an invalid finalization route',
  );
}

if (
  input.operation_status !==
  'failed_retryable'
) {
  throw new Error(
    'Retryable failure result requires operation_status=failed_retryable',
  );
}

if (
  input.case_state !==
  'finalization_failed'
) {
  throw new Error(
    'Retryable failure result requires case_state=finalization_failed',
  );
}

if (!input.next_retry_at) {
  throw new Error(
    'Retryable failure result requires next_retry_at',
  );
}

return {
  json: {
    workflow:
      'WF06',

    result:
      'retry_scheduled',

    case_id:
      input.case_id ?? null,

    correlation_id:
      input.correlation_id ?? null,

    case_state:
      input.case_state,

    operation_id:
      input.operation_id ?? null,

    operation_type:
      input.operation_type ?? null,

    operation_status:
      input.operation_status,

    step_status:
      input.step_status ?? null,

    finalization_outcome:
      input.finalization_outcome ?? null,

    next_retry_at:
      input.next_retry_at,

    requires_intervention:
      false,
  },
};

// Return a controlled WF06 result when manual intervention is required.

const input = $json ?? {};

const preparationIntervention =
  input.next_action ===
    'operator_intervention_required' &&
  input.preparation_outcome !== undefined;

const completionIntervention =
  input.next_action ===
    'operator_intervention_required' &&
  input.completion_outcome !== undefined;

const finalizationIntervention =
  input.finalization_route ===
  'operator_intervention';

if (
  !preparationIntervention &&
  !completionIntervention &&
  !finalizationIntervention
) {
  throw new Error(
    'Operator intervention result received an invalid WF06 route',
  );
}

let interventionReason =
  input.error_code ?? null;

if (
  !interventionReason &&
  input.operation_status === 'failed_terminal'
) {
  interventionReason =
    'operation_failed_terminal';
}

interventionReason ??=
  input.completion_outcome ??
  input.preparation_outcome ??
  input.finalization_outcome ??
  'unexpected_wf06_state';

return {
  json: {
    workflow:
      'WF06',

    result:
      'operator_intervention_required',

    intervention_reason:
      interventionReason,

    case_id:
      input.case_id ?? null,

    correlation_id:
      input.correlation_id ?? null,

    case_state:
      input.case_state ?? null,

    operation_id:
      input.operation_id ?? null,

    operation_type:
      input.operation_type ?? null,

    operation_status:
      input.operation_status ?? null,

    step_status:
      input.step_status ?? null,

    preparation_outcome:
      input.preparation_outcome ?? null,

    completion_outcome:
      input.completion_outcome ?? null,

    finalization_outcome:
      input.finalization_outcome ?? null,

    next_retry_at:
      input.next_retry_at ?? null,

    requires_intervention:
      true,
  },
};
